// os module

const os = require('os');

console.log("Platform:", os.platform());
console.log("Architecture:", os.arch());
console.log("Free Memory:", os.freemem());
console.log("Total Memory:", os.totalmem());
console.log("Hostname:", os.hostname());
//path module
const path = require('path');

const filePath = '/home/student/notes.txt';

console.log("File Name:", path.basename(filePath));
console.log("Directory:", path.dirname(filePath));
console.log("Extension:", path.extname(filePath));
console.log("Joined Path:", path.join('home', 'student', 'file.txt'));
// fs module
const fs = require('fs');

// Write to a file
fs.writeFileSync('sample.txt', 'Hello Node.js');

// Read the file
const data = fs.readFileSync('sample.txt', 'utf8');
console.log(data);

// Append content
fs.appendFileSync('sample.txt', '\nWelcome');

// Read updated content
console.log(fs.readFileSync('sample.txt', 'utf8'));